var irrigationTaskJson = JSON.parse(irrigationTask);
var irrTask = irrigationTaskJson.value;

irrTask.consumption = currentIrrigationWaterConsumption;
irrTask.duration = Date.now() - irrTask.startTs;
var values = {
    "irrigationTask": irrTask
};

if (shouldTurnOff()) {
    values.put("irrigationState", "DONE");
}

return {
    "ts": irrigationTaskJson.ts,
    "values": values
}

function shouldTurnOff() {
    var irrTask = JSON.parse(irrigationTask);
    if (irrTask == null || irrTask.value == null) {
        return true;
    }
    if(irrTask.value.durationThreshold > 0){
        return (irrTask.value.startTs + irrTask.value.durationThreshold) < Date.now();
    } else {
        return currentIrrigationWaterConsumption >= irrTask.value.consumptionThreshold;
    }
}
